const recPattern=/^rec[A-Za-z0-9]{14}$/;
const uuidPattern=/^[a-f0-9]{8}-[a-f0-9]{4}-4[a-f0-9]{3}-[89ab][a-f0-9]{3}-[a-f0-9]{12}$/i;
function exactCycle(value){
 const cycle=value===null||value===undefined||value===''?'initial':String(value);
 if(cycle!=='initial'&&!/^bison:[1-9]\d*:import:[1-9]\d*$/.test(cycle))throw Error('Captured trigger cycle is invalid. No Slack send was authorized.');
 return cycle;
}
function eventKey(recordId,cycleId){return recordId+'|progress_60'+(cycleId==='initial'?'':'|'+cycleId);}
const cfg=input.config();
const recordId=String(cfg.recordId||''),cycleId=exactCycle(cfg.cycleId);
output.set('shouldSend',false);
for(const name of ['recordId','cycleId','attemptId','claimExecutionId','eventKey','taskId','alertText','reason'])output.set(name,'');
if(!recPattern.test(recordId))throw Error('Captured campaign record ID is invalid.');
const auth=input.secret('leadListWebhookAuth');
if(typeof auth!=='string'||!auth)throw Error('Existing coordinator authentication secret is unavailable.');
function attemptUUID(){
 if(typeof crypto!=='undefined'&&typeof crypto.randomUUID==='function')return crypto.randomUUID();
 // This is a unique operation identifier, never an authentication credential.
 return 'xxxxxxxx-xxxx-4xxx-yxxx-xxxxxxxxxxxx'.replace(/[xy]/g,c=>{const r=Math.floor(Math.random()*16);return (c==='x'?r:(r&3)|8).toString(16);});
}
const used=new Set(),maxAttempts=3;
for(let index=0;index<maxAttempts;index++){
 const attemptId=attemptUUID();
 if(!uuidPattern.test(attemptId)||used.has(attemptId))throw Error('A fresh delivery attempt UUID could not be established.');
 used.add(attemptId);
 let response,result;
 try{
  response=await fetch('https://n8n.dulcy.io/webhook/REDACTED_PATH',{method:'POST',headers:{'Content-Type':'application/json','X-Dulcy-Lead-List-Auth':auth},body:JSON.stringify({operation:'claim',recordId,cycleId,attemptId})});
  if(!response.ok)throw Error('non-success response');
  result=await response.json();
 }catch(e){throw Error('Alert claim outcome is failed or uncertain. No Slack send was authorized. Reconcile this exact claim before any retry: '+recordId+' '+cycleId+' '+attemptId+'.');}
 if(result?.ok!==true||typeof result.shouldSend!=='boolean')throw Error('Coordinator did not explicitly authorize delivery. No Slack send was authorized. Reconcile '+recordId+' '+cycleId+' '+attemptId+'.');
 if(result.shouldSend===false&&result.busy===true){
  // Busy consumed this owner ID. Only this explicit response permits a fresh attempt.
  if(index+1===maxAttempts)throw Error('Campaign coordinator remained busy after '+maxAttempts+' distinct attempts. No Slack was sent. Reconcile its current owner before rerunning this automation.');
  continue;
 }
 if(result.shouldSend===false){output.set('reason',String(result.reason||'Coordinator declined this delivery.'));return;}
 if(result.busy===true||result.recordId!==recordId||result.cycleId!==cycleId||result.attemptId!==attemptId||
    !/^\d+$/.test(String(result.claimExecutionId||''))||result.eventKey!==eventKey(recordId,cycleId)||
    !recPattern.test(String(result.taskId||''))||typeof result.alertText!=='string'||!result.alertText.trim()){
  throw Error('Coordinator grant identifiers are inconsistent. No Slack send was authorized. Reconcile '+recordId+' '+cycleId+' '+attemptId+'.');
 }
 for(const name of ['recordId','cycleId','attemptId','claimExecutionId','eventKey','taskId','alertText'])output.set(name,String(result[name]));
 // Set last: a partial/malformed grant must never open the native Slack branch.
 output.set('shouldSend',true);
 return;
}

const recPattern=/^rec[A-Za-z0-9]{14}$/;
const uuidPattern=/^[a-f0-9]{8}-[a-f0-9]{4}-4[a-f0-9]{3}-[89ab][a-f0-9]{3}-[a-f0-9]{12}$/i;
function exactCycle(value){
 const cycle=value===null||value===undefined||value===''?'initial':String(value);
 if(cycle!=='initial'&&!/^bison:[1-9]\d*:import:[1-9]\d*$/.test(cycle))throw Error('Captured trigger cycle is invalid. No Slack send was authorized.');
 return cycle;
}
function eventKey(recordId,cycleId){return recordId+'|progress_60'+(cycleId==='initial'?'':'|'+cycleId);}
// This action runs only after the original native Airtable Slack action succeeds.
// No campaign/task writes and no Slack retry are performed in the source automation.
const cfg=input.config(),recordId=String(cfg.recordId||''),cycleId=exactCycle(cfg.cycleId);
const attemptId=String(cfg.attemptId||''),claimExecutionId=String(cfg.claimExecutionId||'');
if(!recPattern.test(recordId)||!uuidPattern.test(attemptId)||!/^\d+$/.test(claimExecutionId)||cfg.eventKey!==eventKey(recordId,cycleId)||!recPattern.test(String(cfg.taskId||'')))throw Error('Slack action succeeded but exact claim identifiers are missing. Reconcile the completion only. Do not resend Slack.');
const auth=input.secret('leadListWebhookAuth');
if(typeof auth!=='string'||!auth)throw Error('Slack action succeeded but completion authentication is unavailable. Reconcile completion only. Do not resend Slack.');
let response,result;
try{
 response=await fetch('https://n8n.dulcy.io/webhook/REDACTED_PATH',{method:'POST',headers:{'Content-Type':'application/json','X-Dulcy-Lead-List-Auth':auth},body:JSON.stringify({operation:'complete',recordId,cycleId,attemptId,claimExecutionId})});
 if(!response.ok)throw Error('non-success response');
 result=await response.json();
}catch(e){throw Error('Slack action succeeded; completion is failed or uncertain. Reconcile this exact completion only: '+recordId+' '+cycleId+' '+attemptId+' claim '+claimExecutionId+'. Do not resend Slack.');}
if(result?.ok!==true||result.slackSent!==true||result.recordId!==recordId||result.cycleId!==cycleId)throw Error('Slack action succeeded; coordinator completion was not confirmed. Reconcile this exact completion only. Do not resend Slack.');
output.set('completionStatus',result.alreadyProcessing===true?'already_processing':result.alreadyComplete===true?'already_complete':'confirmed');
